let tideDeep={version:2,read:[],talk:[],sms:[],thread:'xun',feedback:'',completed:false,ending:'',identity:'',legacyEnding:tide.solved},deepSelected='';
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion;
 if(p&&p.version===2){tideDeep.read=tideDeepReadKeys.filter(k=>Array.isArray(p.read)&&p.read.includes(k));tideDeep.talk=tideDeepTalkKeys.filter(k=>Array.isArray(p.talk)&&p.talk.includes(k));tideDeep.sms=tideDeepSmsKeys.filter(k=>Array.isArray(p.sms)&&p.sms.includes(k));tideDeep.completed=p.completed===true&&['recorder','notice','mirror','archive2','repairlog','deletedpost','ledger'].every(k=>tideDeep.read.includes(k))&&tideDeep.talk.includes('tape')&&tideDeep.sms.includes('mum-ask');tideDeep.ending=tideDeep.completed&&['sealed','played'].includes(p.ending)?p.ending:'';tideDeep.legacyEnding=p.legacyEnding===true||tide.solved&&!tideDeep.completed;if(tideDeep.completed){tide.solved=true;tide.ending=tideDeep.ending;}}
}catch{}
const tideDeepSaveBase=tideSave;
tideSave=function(){tide.expansion=tideDeep;tideDeepSaveBase();};
function deepMark(key){if(tide.device!=='black'||!tideDeepReadKeys.includes(key))return false;if(!tideDeep.read.includes(key)){tideDeep.read.push(key);tideSave();}return true;}
function deepPhase(){if(tideDeep.completed)return 3;if(tideDeep.talk.includes('tape')&&tideDeep.read.includes('archive2')&&tideDeep.read.includes('mirror'))return 2;return tideDeep.read.length>=3?1:0;}
const tideDeepStageBase=tideStage;
tideStage=function(){if(tide.device!=='black')return tideDeepStageBase();return tideDeep.completed?3:deepPhase()>=2?2:Math.max(Math.min(1,tideDeepStageBase()),Math.min(1,deepPhase()));};
