function deepSmsChoose(id){const c=deepSmsReplies[id];if(!c)return false;if(id==='mum-ask'&&!tideDeep.sms.includes('mum-home'))return false;if(id==='mum-rest'&&!tideDeep.sms.includes('mum-ask'))return false;if(!tideDeep.sms.includes(id)){tideDeep.sms.push(id);tideSave();}return true;}
function deepBubbles(rows){return rows.map(([who,text,time])=>`<div class="deep-bubble ${who==='我'?'from-me':''}"><small>${escapeHTML(who)}${time?' · '+escapeHTML(time):''}</small><p>${escapeHTML(text)}</p></div>`).join('');}
const deepSmsBase=tideSms;
tideSms=function(){if(tide.device!=='black')return deepSmsBase();const m=/^smsdeep:(mum|xun|ordinary)$/.exec(tideView);if(m){const t=deepSmsThreads[m[1]];tideMark('sms');const rows=t.rows.map(r=>[t.name,r[1],r[0]]);for(const id of tideDeep.sms){const c=deepSmsReplies[id];if(c.thread===m[1]){rows.push(['我',c.me,'待发记录']);c.rows.forEach((x,i)=>rows.push([t.name,x,i?'随后':'稍后']));}}let choices='';if(m[1]==='mum'){const id=!tideDeep.sms.includes('mum-home')?'mum-home':!tideDeep.sms.includes('mum-ask')?'mum-ask':'mum-rest';if(!tideDeep.sms.includes(id))choices=`<button data-deep-sms="${id}">${deepSmsReplies[id].me}</button>`;}if(m[1]==='xun'&&!tideDeep.sms.includes('xun-check'))choices='<button data-deep-sms="xun-check">说明手机在我这里</button>';return tideFrame(t.name,`<div class="deep-chat">${deepBubbles(rows)}</div><nav class="deep-choices">${choices}</nav>${tideBtn('sms','返回收件箱')}`);}
 const base=deepSmsBase();return base.replace('<div class="tide-list">',`<div class="deep-contact-list">${deepLink('deep:download','写信息 / 下载代码')}${Object.entries(deepSmsThreads).map(([id,t])=>`<button data-deep-view="smsdeep:${id}"><b>${t.name}</b><span>${t.rows.at(-1)[1].slice(0,25)}…</span></button>`).join('')}</div><details class="deep-old-messages"><summary>早些时候的单条信息</summary><div class="tide-list">`).replace('<form data-tide-compose>','</details><form data-tide-compose>');};
