function deepTalk(id){if(!tideDeepTalkKeys.includes(id)||tideDeep.talk.includes(id))return false;if(id!=='hello'&&!tideDeep.talk.includes('hello'))return false;if(id==='tape')return false;if(id==='room'&&!tideDeep.read.includes('mirror'))return false;if(id==='leave'&&!tideDeep.talk.includes('protect'))return false;tideDeep.talk.push(id);tideSave();return true;}
function deepTapeReply(raw){if(!tideDeep.talk.includes('voice'))return '阿巡：我说的是纸带标签，不是机身型号。我现在真记不清那几个字了。';if(String(raw||'').toUpperCase().replace(/[^A-Z0-9]/g,'')!=='B17')return '阿巡：不像。我印象里那个编号很短，可能被你把破折号看成数字了。';if(!tideDeep.talk.includes('tape'))tideDeep.talk.push('tape');tideSave();return '';}
const deepQQBase=tideQQ;
tideQQ=function(){if(tide.device!=='black'||!['qq:chat','deep:qq'].includes(tideView))return deepQQBase();tideMark('qq');const rows=[['阿巡','在。我这边实验室的网特别慢，你等我一句句发。','10-19 00:12']];for(const id of tideDeep.talk){const c=deepTalkLines[id];rows.push(['我',c.me,'本机对话']);c.rows.forEach((x,i)=>rows.push(['阿巡',x,i?'':'00:'+String(14+tideDeep.talk.indexOf(id)*3).padStart(2,'0')]));}const options=!tideDeep.talk.includes('hello')?['hello']:['bus','voice','protect',...(tideDeep.read.includes('mirror')?['room']:[]),...(tideDeep.talk.includes('protect')?['leave']:[])].filter(k=>!tideDeep.talk.includes(k));return tideFrame('QQ / 阿巡',`<div class="deep-chat">${deepBubbles(rows)}</div><nav class="deep-choices">${options.map(k=>`<button data-deep-talk="${k}">${deepTalkLines[k].me}</button>`).join('')}</nav>${tideDeep.talk.includes('voice')&&!tideDeep.talk.includes('tape')?`<form data-deep-tape><label>接着说一句<input name="label" maxlength="24" aria-label="告诉阿巡标签上的字" placeholder="那张纸带上写着…"></label><button>发送这句留言</button></form>`:''}${tideDeep.feedback?`<p role="status">${escapeHTML(tideDeep.feedback)}</p>`:''}${tideDeep.talk.includes('tape')?'<small>本机记录：收藏夹同步了一份旧页面。</small>':''}${tideBtn('qq','返回好友')}`);};
const deepAlbumBase=tideAlbum;
tideAlbum=function(){if(tide.device!=='black')return deepAlbumBase();const m=/^deep(photo|back|meta):([a-z]+)$/.exec(tideView);if(m){const p=deepPhotos.find(x=>x.id===m[2]);if(!p)return deepAlbumBase();deepMark(p.id);let body;if(m[1]==='back')body=`<article class="tide-photo-back"><p>${p.back}</p></article>${deepLink('deepphoto:'+p.id,'翻回照片')}`;else if(m[1]==='meta')body=`<article><p>${p.name}</p><p>${p.time}</p><p>本机存储卡 / N73</p><small>故事设定时间；原创绘制影像，非原始实拍EXIF。</small></article>${deepLink('deepphoto:'+p.id,'返回照片')}`;else body=`<figure class="tide-photo deep-photo"><img src="images/tide/deep/${p.id}.svg" alt="${p.alt}"></figure><nav class="tide-photo-tools"><button data-tide-zoom>放大 / 还原</button>${deepLink('deepback:'+p.id,'照片背面')}${deepLink('deepmeta:'+p.id,'文件信息')}</nav>`;const i=deepPhotos.indexOf(p);return tideFrame(p.name,body+`<nav class="tide-photo-tools">${deepLink('deepphoto:'+deepPhotos[(i+5)%6].id,'上一张')}${deepLink('deepphoto:'+deepPhotos[(i+1)%6].id,'下一张')}</nav>${tideBtn('photos','缩略图')}`);}
 const base=deepAlbumBase();if(!/^photo:|^back:|^meta:/.test(tideView))return base.replace('3个文件 / 拍摄顺序','9个文件 / 拍摄顺序').replace('<p class="tide-muted">',`<h3 class="deep-album-label">更早的照片 / 未整理</h3><div class="tide-album">${deepPhotos.map(p=>`<button data-deep-view="deepphoto:${p.id}"><img src="images/tide/deep/${p.id}.svg" alt="${p.alt}"><span>${p.name}</span></button>`).join('')}</div><p class="tide-muted">`);return base;};
function deepLink(view,label){return `<button data-deep-view="${view}">${label}</button>`;}
const deepPages={
 archive:{title:'离岸的声音簿 / 2005年11月',read:'archive',body:`<h3>十一月二日，带子在窗台上</h3><p>今天没有出门。风太大，把麦克风放在窗沿，连衣架晃动都录进去了。</p><p>楼下的小孩一直喊人，我没听清他喊谁。翻带面时发现B面已经有东西，只录了不到半分钟。别人的带子，暂时没洗。</p><p>整理编号的时候写错了一次。B-17不是日期，跟前面那十六卷放在一起。</p><p>晚上吃面，忘了加盐。听东西听久了，连饭都没味道。</p>${deepLink('page:archive2','下一页：十一月四日')}`},
 archive2:{title:'离岸的声音簿 / 下一页',read:'archive2',body:`<h3>十一月四日，试着擦掉</h3><p>空白带面能盖掉人声，B-17那段却不行。第二遍回放时，咳嗽声比第一遍多了一下。</p><p>我把带子给修机店看了，他们说是串音。可第一遍明明没有。</p><p>如果后来有人捡到，别拿它当新鲜事传。人留下一句话，不一定是想被别人听见。</p><blockquote>原页此后无更新。缓存记录：2005-11-04。页面标题曾被改为“别让房间安静下来”。</blockquote>${deepLink('page:archive','上一页')}${deepLink('page:ledger','查看页末附件：带库索引.txt')}`},
 ledger:{title:'带库索引.txt',read:'ledger',body:`<h3>旧器材带库 / 残页</h3><table><tr><th>卷号</th><th>登记日</th><th>来源</th></tr><tr><td>A-06</td><td>2004.07</td><td>校园广播试音</td></tr><tr><td>B-16</td><td>2005.10</td><td>街边收音</td></tr><tr><td>B-17</td><td>2005.11.02</td><td>离岸 / 私人留存</td></tr></table><p>2007年器材转让时未逐卷擦除。店员记：带子可能随机器一同卖出，未查明最终去向。</p><p>末尾有一条不同墨色的字：不是他去了海边以后才录到的。</p>${deepLink('page:archive2','返回附件所在页')}`},
 repairlog:{title:'海岸观测站 / 维修记录',read:'repairlog',body:`<h3>S-04检修口 / 状态变更</h3><p>2006年4月：门后旧管道停用，检修口封闭。白天巡查仅从外侧进行。</p><p>2008年10月17日：游客反馈夜间听见敲击。管理员确认当日未安排人员入内；门锁未更换，外侧锈迹连续。</p><p>附注：S-04在堤下，不在灯塔底座。灯塔的设备编号为L-02。</p><p>站方没有判断声音来源。请勿把游客留言当作已核实事故。</p>${deepLink('page:weatherlog','当日环境记录')}`},
 weatherlog:{title:'海岸观测站 / 环境记录',read:'weatherlog',body:`<h3>10月17—18日</h3><p>17日下午无雨，风速6级，玻璃反光明显。夜间转小雨，衣物与鞋底易积水。</p><p>18日03:17最低潮，03:40附近开始回升。早晨09:00风力减弱。</p><p>“门口是干的”不属于本站观测项。本站未安装住宅楼摄像头。</p><small>全部为故事用虚构数据。</small>${deepLink('page:repairlog','返回维修记录')}`},
 profile:{title:'回声采集 / 听潮的人',read:'profile',body:`<h3>会员资料</h3><p>昵称：听潮的人 / 注册于2007年。常驻版面：器材与现场、城市底噪、失败录音。</p><p>签名改过三次：<br>“先别说话，让我录完。”<br>“不是每种声音都要有名字。”<br>“只留下声音，不留下脚印。”</p><p>最近关注：离岸（最后登录2005年11月）。</p><p>最后一条草稿主题：我没有把录音机带回来。</p>${deepLink('forumdeep:returnpost','查看最近主题')}${deepLink('page:archive','关注列表中的旧日志')}`}
};
