function tideDeepCanFinish(){return ['recorder','notice','mirror','archive2','repairlog','deletedpost','ledger'].every(k=>tideDeep.read.includes(k))&&tideDeep.talk.includes('tape')&&tideDeep.sms.includes('mum-ask');}
function tideDeepConclude(source,boundary,handling){if(tide.device!=='black')return '这些记录不是这部手机上的。';if(!tideDeepCanFinish())return '有几句话仍然互相矛盾。现在把纸袋封上，你也许会把两份不同的记录当成同一份。';if(source!=='old'||boundary!=='unconfirmed')return '这会把猜测写成确定发生过的事。再核对旧记录与当晚记录的先后。';if(!['sealed','played'].includes(handling))return '还没有决定怎样保留原件。';tideDeep.completed=true;tideDeep.ending=handling;tide.solved=true;tide.ending=handling;tideSave();return deepEndingText(handling);}
function deepEndingText(handling){return handling==='sealed'?'你分开装好手机卡和旧录音机的照片，写下“B-17：来源早于许舟，未确认声音是谁”。阿巡回了一张早餐照片，说下次一起吃。\n\n你关掉屏幕，雨停了。纸袋里面传来很轻的一声咳嗽。你没有再打开。\n\n《潮声收藏者》扩展篇完。':'你保留了原件，也在故事里留下第二次播放的记录。最初只有转轴声，后来有人开始一字一句重复你和阿巡的对话。\n\n最后一句还没有人说过：“明天早餐，记得给我留一份。”\n\n《潮声收藏者》扩展篇完。';}
const deepJournalBase=tideJournal;
tideJournal=function(){if(tide.device!=='black')return deepJournalBase();return tideFrame(tideDeep.completed?'随手记 / 已归档':'随手记 / 尚未归档',`<p>原来的几行字，只解释了他那晚去了哪里。旧带子、第二份文件和回家后的事，还没有放进同一个纸袋。</p>${tideDeep.legacyEnding?'<p class="tide-muted">旧版结局已保留。这一页是后来整理出来的记录，可以继续往下读。</p>':''}<form data-tide-notes><textarea name="notes" maxlength="1200" aria-label="我的潮声调查笔记">${escapeHTML(tide.notes)}</textarea><button>保存笔记</button></form><details ${tideDeep.feedback||tideDeep.completed?'open':''}><summary>写下准备留给阿巡的话</summary>${tideDeep.feedback||tideDeep.completed?`<p role="status" class="tide-result">${escapeHTML(tideDeep.feedback||deepEndingText(tideDeep.ending))}</p>`:''}${tideDeep.completed?`<p>已归档：${tideDeep.ending==='sealed'?'分开封存':'保留第二遍记录'}</p>`:`<form data-deep-conclude><label>那份额外声音<select name="source"><option value="">我还没想明白</option><option value="new">是许舟当晚第一次录到的</option><option value="old">来自更早留存的B-17，后来才进入手机</option></select></label><label>关于声音的主人<select name="boundary"><option value="">我还没想明白</option><option value="xu">已经证明是许舟自己</option><option value="unconfirmed">记录互有矛盾，无法确认是谁</option></select></label><label>怎样处理原件<select name="handling"><option value="sealed">分开封存，不再重复播放</option><option value="played">保留原件，在故事里留下第二遍记录</option></select></label><button>把这页放进纸袋</button></form>`}</details>${tideBtn('photos','合上笔记')}`);};
const deepJudgeBase=tideJudge;
tideJudge=function(...args){if(tide.device==='black'&&!tideDeep.completed)return '原来的几行字还不够。现在只能记作暂时的判断。';return deepJudgeBase(...args);};
function deepSetView(view){document.querySelector('#modal')?.close();tideView=view;if(/^smsdeep:/.test(view)||view==='deep:download'){phoneState.app='sms';if(view==='deep:download')smsView='compose';}else if(view==='deep:qq')phoneState.app='qq';else if(/^deep(photo|back|meta):/.test(view))phoneState.app='photos';else if(view.startsWith('page:')||['deep:history','deep:bookmarks','deep:wallpapers'].includes(view))phoneState.app='browser';else if(view.startsWith('forumdeep:')||['deep:forum','deep:search'].includes(view))phoneState.app='community';refreshPhone();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-deep-view],[data-deep-talk],[data-deep-sms]');if(!b)return;e.preventDefault();if(b.dataset.deepView)return deepSetView(b.dataset.deepView);if(b.dataset.deepTalk){deepTalk(b.dataset.deepTalk);tideDeep.feedback='';refreshPhone();}if(b.dataset.deepSms){deepSmsChoose(b.dataset.deepSms);refreshPhone();}});
